CREATE OR REPLACE FUNCTION sync_user_note_customer_note() RETURNS TRIGGER AS $$
BEGIN
   IF TG_OP = 'INSERT' THEN
      IF NEW.note IS DISTINCT FROM COALESCE(OLD.note, '') THEN
         NEW.customer_note := NEW.note;
      END IF;
      IF NEW.customer_note IS DISTINCT FROM COALESCE(OLD.customer_note, '') THEN
         NEW.note := NEW.customer_note;
      END IF;
   ELSIF TG_OP = 'UPDATE' THEN
      IF NEW.note IS DISTINCT FROM COALESCE(OLD.note, '') THEN
         NEW.customer_note := NEW.note;
      END IF;
      IF NEW.customer_note IS DISTINCT FROM COALESCE(OLD.customer_note, '') THEN
         NEW.note := NEW.customer_note;
      END IF;
   END IF;
   RETURN NEW;
END;
$$ LANGUAGE plpgsql;
